node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get customer tier
const customer = db.prepare('SELECT loyalty_tier FROM users WHERE user_id = ?').get('user_58b0a2d6');
const tier = customer.loyalty_tier;  // 'standard'

// Get cart items with product shipping_days
const items = db.prepare(\`
  SELECT ci.cart_item_id, ci.quantity, p.name, p.shipping_days
  FROM cart_items ci
  JOIN products p ON ci.product_id = p.product_id
  WHERE ci.customer_id = ?
\`).all('user_58b0a2d6');

const totalItemCount = items.reduce((sum, i) => sum + i.quantity, 0);
const maxShippingDays = Math.max(...items.map(i => i.shipping_days));

console.log('Tier:', tier);
console.log('Total items (units):', totalItemCount);
console.log('Max product shipping days:', maxShippingDays);
console.log('Items:');
items.forEach(i => console.log('  ' + i.name + ': qty=' + i.quantity + ', ships in ' + i.shipping_days + ' days'));

// Shipping options per policy
const STANDARD_FEE = 6, EXPRESS_FEE = 12, NEXT_DAY_FEE = 15;
const FREE_THRESHOLD = 5;

// Standard
const stdCost = totalItemCount >= FREE_THRESHOLD ? 0 : STANDARD_FEE;
const stdEta = Math.max(maxShippingDays, 1);

// Express: free for gold/platinum
const expCost = ['gold','platinum'].includes(tier) ? 0 : EXPRESS_FEE;
const expEta = Math.max(maxShippingDays - 1, 1);

// Next day: free for platinum only
const ndCost = tier === 'platinum' ? 0 : NEXT_DAY_FEE;

console.log('\n=== SHIPPING OPTIONS ===');
console.log('Standard:  cost=\$' + stdCost + ', ETA=' + stdEta + ' business days' + (totalItemCount >= FREE_THRESHOLD ? ' (free: 5+ items)' : ''));
console.log('Express:   cost=\$' + expCost + ', ETA=' + expEta + ' business days' + (expCost === 0 ? ' (free: ' + tier.charAt(0).toUpperCase() + tier.slice(1) + ' perk)' : ''));
console.log('Next-day:  cost=\$' + ndCost + ', ETA=next business day' + (ndCost === 0 ? ' (free: Platinum perk)' : ''));

db.close();
"

